def build_tag_report(raw_tags, required_tags):
    existing = {tag.lower() for tag in raw_tags}
    required = {tag.lower() for tag in required_tags}
    return {
        'all': sorted(existing),
        'missing': sorted(required - existing),
        'shared': sorted(existing & required),
    }

