$m2_l7_t6_starter$, $m2_l7_t6_solution$from typing import Protocol

class Readable(Protocol):
    def read(self) -> str: ...

def read_non_empty(source: Readable) -> str:
    text = source.read()
    if not text:
        raise ValueError("empty source")
