$m2_l24_t9_starter$, $m2_l24_t9_solution$class RealClient:
    def post(self, payload):
        raise RuntimeError('real network')


def notify(client, email):
    return client.post({'email': email})


class FakeClient:
    def __init__(self):
        self.calls = []
    def post(self, payload):
        self.calls.append(payload)
        return {'ok': True}


def test_notify():
    client = FakeClient()
    assert notify(client, 'a@b.com')['ok'] is True
    assert client.calls == [{'email': 'a@b.com'}]
