$m5_l12_t4_starter$, $m5_l12_t4_solution$def review_diff(diff: str) -> dict:
    lower = diff.lower()
    risks = []
    if 'sk-' in diff:
        risks.append('secret')
    if 'assert' not in lower and 'pytest' not in lower:
        risks.append('missing_check')
    return {'approved': not risks, 'risks': risks}
